<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:11px}h1{color:#1D80F7;margin:0}.top{border-bottom:2px solid #1D80F7;padding-bottom:16px}.right{float:right;text-align:right}.columns{width:100%;margin-top:20px}.columns td{vertical-align:top;width:50%}table.lines{width:100%;border-collapse:collapse;margin-top:25px}.lines th,.lines td{padding:9px;border-bottom:1px solid #cbd5e1}.number{text-align:right}.totals{margin-left:auto;margin-top:20px;width:45%}.totals td{padding:5px}.grand{font-size:16px;font-weight:bold;border-top:2px solid #64748b}.note{margin-top:25px;padding:12px;border:1px solid #cbd5e1}</style></head><body>
<div class="top"><div class="right"><strong>INVOICE</strong><h1>{{ $invoice->invoice_number }}</h1><p>Issued {{ $invoice->issued_at?->timezone($invoice->organization->timezone)->format('M j, Y') }}</p></div><img src="{{ $logoDataUri }}" alt="{{ $invoice->seller_name }}" style="max-height:70px;max-width:220px"><p>{{ $invoice->seller_phone }} · {{ $invoice->seller_email }}</p></div>
