<p><strong>{{ $invoice->serviceTicket->ticket_number }}</strong> · {{ $invoice->serviceTicket->title }}</p>
<table class="lines"><thead><tr><th>Description</th><th class="number">Qty</th><th class="number">Rate</th><th class="number">Amount</th></tr></thead><tbody>@foreach($invoice->lines->where('included',true) as $line)<tr><td>{{ $line->description }}</td><td class="number">{{ rtrim(rtrim(number_format($line->quantity_millis/1000,3,'.',''),'0'),'.') }} {{ $line->unit }}</td><td class="number">${{ number_format($line->unit_price_cents/100,2) }}</td><td class="number">${{ number_format($line->total_cents/100,2) }}</td></tr>@endforeach</tbody></table>
<table class="totals"><tr><td>Subtotal</td><td class="number">${{ number_format($invoice->subtotal_cents/100,2) }}</td></tr><tr><td>Discount</td><td class="number">-${{ number_format($invoice->discount_total_cents/100,2) }}</td></tr><tr><td>Tax</td><td class="number">${{ number_format($invoice->tax_total_cents/100,2) }}</td></tr><tr class="grand"><td>Total</td><td class="number">${{ number_format($invoice->total_cents/100,2) }}</td></tr></table>
<p class="right"><strong>{{ $invoice->payment_terms==='due_on_receipt' ? 'Due on receipt' : 'Due '.$invoice->due_on?->format('M j, Y') }}</strong></p>@if($invoice->customer_note)<div class="note"><strong>Note</strong><p>{{ $invoice->customer_note }}</p></div>@endif
</body></html>
